def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    edge = Counter()
    for c in range(w):
        if grid[0][c] != bg:
            edge[grid[0][c]] += 1
        if grid[h - 1][c] != bg:
            edge[grid[h - 1][c]] += 1
    for r in range(h):
        if grid[r][0] != bg:
            edge[grid[r][0]] += 1
        if grid[r][w - 1] != bg:
            edge[grid[r][w - 1]] += 1
    marker = edge.most_common(1)[0][0]

    seeds = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != marker]
    if not seeds:
        return [row[:] for row in grid]
    ray_color = Counter(grid[r][c] for r, c in seeds).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def segments(values):
        result = []
        current = []
        for i, v in enumerate(values):
            if v == marker:
                current.append(i)
            elif current:
                result.append(current)
                current = []
        if current:
            result.append(current)
        return result

    horizontal = sum(grid[r][c] == marker for r in (0, h - 1) for c in range(w))
    vertical = sum(grid[r][c] == marker for c in (0, w - 1) for r in range(h))

    if horizontal >= vertical:
        top, bottom = segments(grid[0]), segments(grid[h - 1])
        all_segments = [(s, 0, 1) for s in top] + [(s, h - 1, -1) for s in bottom]
        varying_coords = [c for r, c in seeds]
        edge_collections = [top, bottom]
    else:
        left = segments([grid[r][0] for r in range(h)])
        right = segments([grid[r][w - 1] for r in range(h)])
        all_segments = [(s, 0, 1) for s in left] + [(s, w - 1, -1) for s in right]
        varying_coords = [r for r, c in seeds]
        edge_collections = [left, right]

    # Determine the selected lane offsets from the edge segment(s) aligned
    # with the interior objects, then use the same offsets on the other edge.
    offsets = set()
    for collection in edge_collections:
        for seg in collection:
            for r, c in seeds:
                p = c if horizontal >= vertical else r
                if p in seg:
                    offsets.add(seg.index(p))
    if not offsets:
        offsets = {0}

    seed_set = set(seeds)
    for seg, edge_pos, direction in all_segments:
        chosen = [seg[o] for o in sorted(offsets) if o < len(seg)]
        for p in chosen:
            if horizontal >= vertical:
                r, c = edge_pos + direction, p
                while 0 <= r < h:
                    if grid[r][c] == marker:
                        break
                    if (r, c) in seed_set:
                        out[r][c] = 4
                        break
                    out[r][c] = ray_color
                    r += direction
            else:
                r, c = p, edge_pos + direction
                while 0 <= c < w:
                    if grid[r][c] == marker:
                        break
                    if (r, c) in seed_set:
                        out[r][c] = 4
                        break
                    out[r][c] = ray_color
                    c += direction

    for r, c in seeds:
        out[r][c] = 4
    return out
